<?php
if(PHP_SAPI!=='cli'||!isset($db,$work))exit;
if(!preg_match('/^tooltrack_test_[a-f0-9]{12}$/',(string)$db->query('SELECT DATABASE()')->fetchColumn()))throw new RuntimeException('Stock tests require an isolated database.');
require_once dirname(__DIR__).'/includes/stock_lib.php';
installStockHistory($db);
$tool=expectApi('Register stock-tracked tool','tools.php','POST',['name'=>'Stock Test Tool','category'=>'Cookware','quantity'=>8,'min_stock'=>1,'price'=>5]);
$stockId=(int)$tool['id'];$sku=$tool['code'];
$registered=$db->query("SELECT * FROM stock_history WHERE tool_id=$stockId AND event_kind='registration'")->fetch();
check((int)$registered['quantity']===8&&(int)$registered['previous_stock']===0&&(int)$registered['updated_stock']===8,'Registration logs initial stock exactly once');
check($registered['tool_code']===$sku&&(int)$registered['user_id']===1&&$registered['user_name']==='Test Admin'&&$registered['created_at']===$tool['created_at'],'Registration records SKU, exact timestamp and responsible user');
$body=['action'=>'add_stock','id'=>$stockId,'quantity'=>5,'request_token'=>'stock_test_00000001','remarks'=>'Test delivery'];
expectApi('Staff cannot restock','tools.php','POST',$body,false,'Staff');
foreach([0,-1,1.5,'abc','',true,100001] as $bad){expectApi('Invalid restock quantity rejected','tools.php','POST',array_merge($body,['quantity'=>$bad]),false);}
$first=expectApi('Admin adds stock','tools.php','POST',$body);
// The comparison happens while the tool is locked, before any stock is written.
$reviewBody=array_merge($body,['request_token'=>'stock_review_conflict','expected_stock'=>['quantity'=>8,'available'=>8]]);
$changed=expectApi('Stale stock review returns refreshed counts','tools.php','POST',$reviewBody);
check(!empty($changed['stock_changed'])&&(int)row('tools',$stockId)['quantity']===13,'Stale review leaves inventory unchanged');
$reviewBody['expected_stock']=['quantity'=>13,'available'=>12];
$changed=expectApi('Available-only change also requires review','tools.php','POST',$reviewBody);
check(!empty($changed['stock_changed'])&&(int)row('tools',$stockId)['quantity']===13,'Available conflict leaves inventory unchanged');
check((int)$first['tool']['quantity']===13&&(int)$first['tool']['available']===13&&$first['tool']['code']===$sku,'Restock updates totals and preserves SKU');
$duplicate=expectApi('Restock retry is idempotent','tools.php','POST',$body);
check($duplicate['duplicate']&&(int)row('tools',$stockId)['quantity']===13,'Duplicate request does not add units twice');
check((int)$db->query("SELECT COUNT(*) FROM stock_history WHERE request_token='stock_test_00000001'")->fetchColumn()===1,'Duplicate restock creates one history event');
expectApi('Token cannot be reused with different quantity','tools.php','POST',array_merge($body,['quantity'=>6]),false);
$once=array_merge($body,['quantity'=>2,'request_token'=>'stock_test_race_same']);
$race=concurrentApi('tools.php','POST',$once,8);
check(count(array_filter($race,fn($r)=>$r['success']))===8,'Simultaneous retries all receive safe responses');
check(count(array_filter($race,fn($r)=>empty($r['data']['duplicate'])))===1&&(int)row('tools',$stockId)['quantity']===15,'Eight simultaneous retries apply one addition');
$bodies=[];for($i=0;$i<8;$i++)$bodies[]=array_merge($body,['quantity'=>1,'request_token'=>'stock_unique_parallel_'.str_pad((string)$i,3,'0',STR_PAD_LEFT)]);
$race=concurrentApi('tools.php','POST',$body,8,$bodies);
check(count(array_filter($race,fn($r)=>$r['success']))===8&&(int)row('tools',$stockId)['quantity']===23,'Different concurrent additions do not lose stock updates');
$before=expectApi('Read dashboard before restock','dashboard.php','GET');
$loan=expectApi('Borrow stock-tracked tool','transactions.php','POST',['type'=>'borrow','tool_code'=>$sku,'borrower_id'=>1,'qty'=>5,'due_date'=>date('Y-m-d',strtotime('+1 day'))]);
expectApi('Mixed return before restock','transactions.php','POST',['type'=>'return','borrow_txn_id'=>$loan['id'],'returnee_name'=>'Test Borrower','request_token'=>'restock_mixed_return','items'=>['good'=>1,'minor'=>1,'damaged'=>1,'missing'=>1],'missing_reason'=>'Stock tracking test','missing_date'=>date('Y-m-d')]);
$state=row('tools',$stockId);$before=expectApi('Dashboard current inventory','dashboard.php','GET');
$added=expectApi('Restock with active loans and condition buckets','tools.php','POST',array_merge($body,['quantity'=>10,'request_token'=>'stock_condition_test']));
$after=expectApi('Dashboard after restock','dashboard.php','GET');$updated=row('tools',$stockId);
check((int)$updated['quantity']===(int)$state['quantity']+10&&(int)$updated['available']===(int)$state['available']+10,'Restock adds only good available stock');
foreach(['minor_qty','damaged_qty','missing_qty','original_quantity','code','created_at'] as $field)check($updated[$field]===$state[$field],'Restock preserves '.$field);
check($after['total_tools']===$before['total_tools']+10&&$after['available_tools']===$before['available_tools']+10&&$after['borrowed_tools']===$before['borrowed_tools'],'Dashboard totals increase without changing borrowed count');
check($after['total_units']===$before['total_units']+10&&$after['total_tool_types']===$before['total_tool_types'],'Restocking changes Dashboard units without creating a tool type');
expectApi('Stale editor cannot overwrite added stock','tools.php','PUT',['id'=>$stockId,'name'=>'Stock Test Tool','code'=>$sku,'category'=>'Cookware','quantity'=>$state['quantity'],'previous_quantity'=>$state['quantity'],'min_stock'=>1,'price'=>5],false);
expectApi('Retire tool for restock validation','tools.php','PATCH',['id'=>$stockId,'is_active'=>false]);
expectApi('Retired tool cannot receive stock','tools.php','POST',array_merge($body,['request_token'=>'stock_retired_token']),false);
expectApi('Reactivate stock tool','tools.php','PATCH',['id'=>$stockId,'is_active'=>true]);
$db->exec("CREATE TRIGGER stock_test_fail BEFORE INSERT ON stock_history FOR EACH ROW BEGIN IF NEW.remarks='Simulated history failure' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Test history failure'; END IF; END");
$quantity=(int)row('tools',$stockId)['quantity'];
try{expectApi('History failure rolls back restock','tools.php','POST',array_merge($body,['request_token'=>'stock_history_failure','remarks'=>'Simulated history failure']),false);}
finally{$db->exec('DROP TRIGGER stock_test_fail');}
check((int)row('tools',$stockId)['quantity']===$quantity,'Failed stock event changes no inventory');
expectApi('Retry after failed transaction succeeds','tools.php','POST',array_merge($body,['request_token'=>'stock_history_failure']));
$cap=expectApi('Create high-stock tool','tools.php','POST',['name'=>'Capacity Tool','category'=>'Utensils','quantity'=>99999,'min_stock'=>1,'price'=>1]);
expectApi('Reject addition exceeding capacity','tools.php','POST',['action'=>'add_stock','id'=>$cap['id'],'quantity'=>2,'request_token'=>'stock_capacity_test'],false);
expectApi('Accept addition up to capacity','tools.php','POST',['action'=>'add_stock','id'=>$cap['id'],'quantity'=>1,'request_token'=>'stock_capacity_test']);
$db->prepare("UPDATE stock_history SET created_at='1999-01-02 09:30:00' WHERE id=?")->execute([$registered['id']]);
$db->prepare("UPDATE stock_history SET created_at='1999-01-02 09:45:00' WHERE id=?")->execute([$first['history_id']]);
$report=expectApi('Stock History by date','reports.php','GET',[],true,'Admin',['type'=>'stock_history','date_from'=>'1999-01-02','date_to'=>'1999-01-02']);
check($report['total']===2&&$report['totals']['units_added']===13&&$report['totals']['tools_registered']===1&&$report['totals']['restocked_units']===5,'Daily totals combine registrations and restocks without double counting');
check(count($report['daily'])===1&&$report['daily'][0]['date']==='01/02/1999','Report provides per-day quantities');
check($report['rows'][0][0]==='01/02/1999 9:45 AM'&&$report['rows'][1][0]==='01/02/1999 9:30 AM','History timestamps use numeric date and AM/PM time');
check($report['rows'][0][3]===$sku&&$report['rows'][0][7]==='Test Admin','Stock History shows unchanged SKU and admin');
$cmd=[PHP_BINARY,$work.'/worker.php','reports.php','GET','{}','Admin','type=stock_history&download=1&date_from=1999-01-02&date_to=1999-01-02'];
$p=proc_open($cmd,[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);fclose($pipes[0]);$csv=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);proc_close($p);
check(str_contains($csv,'01/02/1999 9:45 AM')&&substr_count($csv,$sku)===2,'Stock History CSV respects dates and timestamps');
expectApi('Invalid report dates rejected','reports.php','GET',[],false,'Admin',['type'=>'stock_history','date_from'=>'1999-02-31']);
expectApi('Reversed report range rejected','reports.php','GET',[],false,'Admin',['type'=>'stock_history','date_from'=>'2000-01-01','date_to'=>'1999-01-01']);
// Seed a large isolated day to verify daily totals cover all events, not just the 200-row screen preview.
$quantity=(int)row('tools',$stockId)['quantity'];$db->beginTransaction();
for($i=1;$i<=205;$i++)$db->prepare("INSERT INTO stock_history(tool_id,tool_name,tool_code,transaction_type,quantity,previous_stock,updated_stock,user_id,user_name,event_kind,created_at) VALUES (?,?,?,'Stock Added',1,?,?,1,'Test Admin','restock','1998-01-01 10:00:00')")->execute([$stockId,'Stock Test Tool',$sku,$quantity+$i-1,$quantity+$i]);
$db->prepare('UPDATE tools SET quantity=quantity+205,available=available+205 WHERE id=?')->execute([$stockId]);$db->commit();
$large=expectApi('Large Stock History day','reports.php','GET',[],true,'Admin',['type'=>'stock_history','date_from'=>'1998-01-01','date_to'=>'1998-01-01']);
check($large['total']===205&&count($large['rows'])===25&&$large['page']===1&&$large['totals']['units_added']===205,'Daily totals include records beyond the current page');
$count=(int)$db->query('SELECT COUNT(*) FROM stock_history')->fetchColumn();installStockHistory($db);check((int)$db->query('SELECT COUNT(*) FROM stock_history')->fetchColumn()===$count,'Stock migration rerun does not duplicate history');
$all=expectApi('Full Stock History includes legacy registrations','reports.php','GET',[],true,'Admin',['type'=>'stock_history']);
check($all['totals']['unknown_registrations']>0,'Unknown historical quantities are explicit instead of invented');
invariant();check(true,'All restock, history and condition operations preserve inventory conservation');
